			dw p_bul_aim_r

			; Bul.cls 729: End If
if127_1:

			; Bul.cls 730: If ax <= ay Then
			dw kw_scplevv, var_bul_aim_ax, var_bul_aim_ay
			dw kw_goto_iffalse, if128_1

			; Bul.cls 731: t = atn(ax * 16 \ ay)
			dw kw_mulvl, var_bul_aim_ax, 16, tmp2
			dw kw_divvv, tmp2, var_bul_aim_ay, tmp2
			dw kw_aget, arr_bul_atn, tmp2, var_bul_aim_t

