			; Bul.cls 733: t = 64 - atn(ay * 16 \ ax)
			dw kw_mulvl, var_bul_aim_ay, 16, tmp3
			dw kw_divvv, tmp3, var_bul_aim_ax, tmp3
			dw kw_aget, arr_bul_atn, tmp3, tmp3
