			dw kw_goto_iffalse, if130_1
			dw kw_vtov, var_bul_aim_t, var_bul_aim_aim
			dw if129_e_go
if130_1:
			dw kw_sublv, 256, var_bul_aim_t, tmp2
			dw kw_andvl, tmp2, 255, var_bul_aim_aim
if130_e:

			; Bul.cls 737: Else
			dw if129_e_go
if129_1:

			; Bul.cls 738: If dx >= 0 Then Aim = 128 - t Else Aim = 128 + t
			dw kw_scpgevl, var_bul_aim_dx, 0
			dw kw_goto_iffalse, if131_1
